import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/material.dart';

/// Rasterized from the 20 px icons published with the official MetaTrader 5
/// iPhone help. Keeping the source pixels avoids font/platform glyph drift.
enum MtSettingsRasterIconKind {
  newAccount,
  mail,
  news,
  tradays,
  messages,
  community,
  telegram,
  otp,
  interface,
  charts,
  journal,
  about,
}

class MtSettingsRasterIcon extends StatelessWidget {
  const MtSettingsRasterIcon(this.kind, {this.size = 28, super.key});

  final MtSettingsRasterIconKind kind;
  final double size;

  static final Map<MtSettingsRasterIconKind, Uint8List> _decoded = {
    for (final entry in _encoded.entries) entry.key: base64Decode(entry.value),
    for (final entry in _videoEncoded.entries)
      if (entry.key != MtSettingsRasterIconKind.messages)
        entry.key: base64Decode(entry.value),
  };

  @override
  Widget build(BuildContext context) => SizedBox(
    width: size * 1.0238095238,
    height: size * 1.0476190476,
    child: Image.memory(
      _decoded[kind]!,
      fit: BoxFit.fill,
      filterQuality:
          _videoEncoded.containsKey(kind) &&
              kind != MtSettingsRasterIconKind.messages
          ? FilterQuality.none
          : FilterQuality.high,
      gaplessPlayback: true,
      excludeFromSemantics: true,
    ),
  );
}

const Map<MtSettingsRasterIconKind, String> _videoEncoded = {
  MtSettingsRasterIconKind.messages:
      '',
  MtSettingsRasterIconKind.newAccount:
      '',
  MtSettingsRasterIconKind.mail:
      '',
  MtSettingsRasterIconKind.news:
      '',
  MtSettingsRasterIconKind.tradays:
      '',
  MtSettingsRasterIconKind.community:
      '',
  MtSettingsRasterIconKind.telegram:
      '',
  MtSettingsRasterIconKind.otp:
      '',
  MtSettingsRasterIconKind.interface:
      '',
};

const Map<MtSettingsRasterIconKind, String> _encoded = {
  MtSettingsRasterIconKind.newAccount:
      '',
  MtSettingsRasterIconKind.mail:
      '',
  MtSettingsRasterIconKind.news:
      '',
  MtSettingsRasterIconKind.tradays:
      '',
  MtSettingsRasterIconKind.messages:
      '',
  MtSettingsRasterIconKind.community:
      '',
  MtSettingsRasterIconKind.otp:
      '',
  MtSettingsRasterIconKind.interface:
      '',
  MtSettingsRasterIconKind.charts:
      '',
  MtSettingsRasterIconKind.journal:
      '',
  MtSettingsRasterIconKind.about:
      '',
};
